const e=[{id:"sv-2-541",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"On a standard process map, what does a **rectangle** represent?",options:["The start or the end of the process","An activity or task performed in the process","A decision with a Yes and a No path","Data or a document used by the process"],answer:1,hint:"Recall the six standard flowchart symbols and what each one stands for.",steps:[{title:"Key idea",body:"The book's symbol table: rectangle = activity, diamond = decision, parallelogram = data, ellipse = start/end."},{title:"Eliminate look-alikes",body:"Only the activity is drawn as a rectangle; the other shapes are look-alike symbols."}],final:"Rectangle = activity → answer **B**",whyWrong:["Incorrect — the start and end points are drawn as ellipses (ovals).","","Incorrect — a decision is drawn as a diamond.","Incorrect — data is drawn as a parallelogram."],bookRef:"Book p. 101"},{id:"sv-2-542",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Which symbol marks the **start or end** of a process on a standard process map?",options:["Ellipse (oval)","Circle containing a letter","Diamond","Parallelogram"],answer:0,hint:"Each standard shape has one meaning; think which one bounds the flow.",steps:[{title:"Key idea",body:"Ellipses open and close the process map."},{title:"Eliminate look-alikes",body:"Diamond = decision, parallelogram = data, lettered circle = continues on another page."}],final:"Ellipse = start/end → answer **A**",whyWrong:["","Incorrect — a small lettered circle is an off-page connector: the flow continues on another page.","Incorrect — a diamond is a decision point with Yes and No exits.","Incorrect — a parallelogram shows data."],bookRef:"Book p. 101"},{id:"sv-2-543",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"In a SIPOC, what does the **process (P)** column usually contain?",options:["The names of the people who perform each step","A high-level map of about 4–8 steps","Every decision in the process with its Yes and No paths","A detailed Level 3 map with performance data"],answer:1,hint:"A SIPOC is a high-level, one-page view.",steps:[{title:"Key idea",body:"The book: the 'P' of a SIPOC is a high-level map of about 4–8 steps."},{title:"Eliminate look-alikes",body:"Performance data, decisions and ownership need more detailed maps."}],final:"P = 4–8 high-level steps → answer **B**",whyWrong:["Incorrect — who does each step is shown on a swim lane map.","","Incorrect — detailed decisions belong on a Level 2 map.","Incorrect — performance data belongs on a Level 3 map, not in a SIPOC."],bookRef:"Book p. 111"},{id:"sv-2-544",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"On a process map, what does a small **circle containing a letter or number** indicate?",options:["An inspection point in the process","A delay where work waits","The flow continues on another page","A data store used by the step"],answer:2,hint:"Think of how a long flowchart is split across pages.",steps:[{title:"Key idea",body:"The lettered or numbered circle is a connector: it links the flow to the same letter on another page."},{title:"Eliminate look-alikes",body:"It carries no meaning about data, inspection or delay."}],final:"Lettered circle = off-page connector → answer **C**",whyWrong:["Incorrect — the book's symbol set has no special inspection circle; inspections are activities.","Incorrect — waiting is not shown with a lettered circle; on a VSM queues appear as inventory.","","Incorrect — data is drawn as a parallelogram."],bookRef:"Book p. 101"},{id:"sv-2-545",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"What do the **arrows** on a standard process map show?",options:["The direction in which the work flows","The cost added by each activity","The time each activity takes","The person responsible for the next step"],answer:0,hint:"Arrows connect the shapes; what do they tell the reader?",steps:[{title:"Key idea",body:"In the symbol table an arrow means direction of flow."},{title:"Eliminate look-alikes",body:"Time, cost and ownership need other elements: data boxes, performance data or lanes."}],final:"Arrow = direction of flow → answer **A**",whyWrong:["","Incorrect — arrows carry no cost information.","Incorrect — times appear in data boxes or on a Level 3 map, not as arrows.","Incorrect — responsibility is shown by swim lanes."],bookRef:"Book p. 101"},{id:"sv-2-546",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which describes a **Level 3 (micro)** process map?",options:["A map of only the major steps, used to show where the process fits in the big picture","A detailed map that adds performance data such as yields, cycle times, VA/NVA time and DPU","A one-page table of suppliers, inputs, process, outputs and customers","A map of the major steps as the worker does them, including decisions"],answer:1,hint:"Level 1 → 2 → 3 adds detail; only one level adds performance data.",steps:[{title:"Key idea",body:"Level 3 is the improvement view: more steps plus data — yields, cycle times, VA/NVA time, defects, DPU, RTY."},{title:"Eliminate look-alikes",body:"Level 1 = big picture, Level 2 = worker view, SIPOC = suppliers-to-customers summary."}],final:"Level 3 = steps + performance data → answer **B**",whyWrong:["Incorrect — this describes the Level 1 macro (management) map.","","Incorrect — this describes a SIPOC.","Incorrect — this describes the Level 2 (worker) map."],bookRef:"Book pp. 102–103"},{id:"sv-2-547",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"What is the main purpose of a **Level 1 (macro)** process map?",options:["To show only the major steps and where the process fits in the big picture","To record the cycle time and yield of each task","To show every decision the worker makes","To show which department performs each task"],answer:0,hint:"The macro map is the management view.",steps:[{title:"Key idea",body:"Level 1 shows major steps with minimal detail, usually 4–8 steps, so managers see the big picture."},{title:"Eliminate look-alikes",body:"Ownership, performance data and detailed decisions belong to other maps."}],final:"Level 1 = major steps, big picture → answer **A**",whyWrong:["","Incorrect — performance data belongs on a Level 3 map.","Incorrect — decisions as the worker meets them belong on a Level 2 map.","Incorrect — that is the job of a swim lane (deployment) map."],bookRef:"Book p. 102"},{id:"sv-2-548",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"The book compares the three levels of process map to which familiar set of maps?",options:["Floor, building and site plans","World, country and city maps","Weather, terrain and political maps","Road, rail and air maps"],answer:1,hint:"Think of zooming in from the big picture to the detail.",steps:[{title:"Key idea",body:"Level 1 is like a world map, Level 2 a country map, Level 3 a city map: each zooms in further."},{title:"Apply to the stem",body:"Only the world–country–city set shows the same area at growing detail."}],final:"World → country → city → answer **B**",whyWrong:["Incorrect — the book does not use building plans; its analogy is geographic zoom.","","Incorrect — these are different map subjects, not levels of detail.","Incorrect — these are transport maps; they do not show increasing levels of detail."],bookRef:"Book p. 102"},{id:"sv-2-549",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"How is the **value-added test** applied to the steps on a process map?",options:["By counting the hand-offs between lanes and marking each crossing as value-added","By asking the process owner which steps are required by the procedure and marking those as value-added","By timing each step and marking the slowest steps as non-value-added","By asking whether each step changes the form, fit or function of the item and whether the customer would pay for it, and marking failures as NVA"],answer:3,hint:"Recall the book's two questions for each step.",steps:[{title:"Key idea",body:"Two questions: does it change form, fit or function, and is the customer willing to pay for it?"},{title:"Apply to the stem",body:"A step that fails is non-value-added and is marked on the map with a red X or 'NVA'."}],final:"Form/fit/function + customer pays → answer **D**",whyWrong:["Incorrect — hand-offs are where queues form; they never add value.","Incorrect — required steps such as reviews or inspections are usually still non-value-added.","Incorrect — a slow step can still add value; speed is not the test.",""],bookRef:"Book p. 117"},{id:"sv-2-550",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"In the book's preferred order for building a SIPOC, what is identified immediately **after the customers**?",options:["The suppliers","The process steps","The customer requirements","The inputs"],answer:2,hint:"The order works backwards from what the customer receives.",steps:[{title:"Key idea",body:"Preferred order: outputs → customers → customer requirements → inputs → suppliers → input requirements."},{title:"Apply to the stem",body:"The element after customers is the customer requirements."}],final:"Customers → customer requirements → answer **C**",whyWrong:["Incorrect — suppliers are identified after the inputs.","Incorrect — the process is a 4–8 step map; the order starts from outputs and customers.","","Incorrect — inputs come after the customer requirements."],bookRef:"Book p. 111"},{id:"sv-2-551",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"What does a **value stream map** show that a basic linear process map does not?",options:["The decision points where work goes one way or another","The speed of the process, queue sizes and performance data for each major step","The direction of flow between activities","The sequence of the major steps from start to end"],answer:1,hint:"What extra data does a VSM carry?",steps:[{title:"Key idea",body:"A VSM adds speed, queues and per-step performance, which makes it good for finding bottlenecks."},{title:"Eliminate look-alikes",body:"Sequence, decisions and flow direction are common to all process maps."}],final:"VSM adds speed, queues, performance → answer **B**",whyWrong:["Incorrect — decisions are already shown on a basic map with diamonds.","","Incorrect — arrows on any map show the direction of flow.","Incorrect — every process map shows the sequence of steps."],bookRef:"Book p. 105"},{id:"sv-2-552",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Using the book's hint, which step name is MOST likely to be non-value-added?",options:["Activate the mobile line","Rewrite the service order after rejection","Configure the customer's router","Splice the fibre at the cabinet"],answer:1,hint:"Look at how the step's verb begins.",steps:[{title:"Key idea",body:"Steps that begin with 're' — rework, replace, review, rewrite — are very likely waste."},{title:"Apply to the stem",body:"'Rewrite the service order' repeats work already done; the others change the service."}],final:"'Re-' step = likely waste → answer **B**",whyWrong:["Incorrect — activation delivers the service the customer is paying for.","","Incorrect — configuring the router changes the function the customer receives.","Incorrect — splicing changes the physical service the customer pays for."],bookRef:"Book p. 117"},{id:"sv-2-553",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Which set lists the **three views of a process** described in the book?",options:["What you think it is, what it actually is, what it should be","Level 1, Level 2 and Level 3","Value-added, non-value-added and business-value-added","Supplier view, process view, customer view"],answer:0,hint:"The views differ in how close they are to reality.",steps:[{title:"Key idea",body:"The book: what you think it is, what it actually is, what it should be."},{title:"Eliminate look-alikes",body:"SIPOC parts, map levels and VA categories are other lists."}],final:"Think / actually is / should be → answer **A**",whyWrong:["","Incorrect — these are levels of map detail, not views.","Incorrect — these classify activities, not views of the whole process.","Incorrect — these are the SIPOC perspectives, not the views of a process."],bookRef:"Book p. 100"},{id:"sv-2-554",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Compared with what people think, how is the **actual** process usually described in the book?",options:["Smaller and simpler, because people overestimate it","Faster, because people overestimate the waiting time","About the same, because the procedure describes it well","Bigger, harder and more costly, with hidden operations"],answer:3,hint:"Why must the team walk the process?",steps:[{title:"Key idea",body:"The real process is almost always bigger, harder and more costly than people think, with hidden operations."},{title:"Apply to the stem",body:"That is why the 'actually is' view must be found by walking the process."}],final:"Actual = bigger, hidden operations → answer **D**",whyWrong:["Incorrect — the book says the reverse: hidden steps make it larger.","Incorrect — real processes usually hide extra waiting and rework.","Incorrect — written procedures miss the hidden work and loops.",""],bookRef:"Book p. 100"},{id:"sv-2-555",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which is a purpose of process mapping?",options:["To calculate the process capability index","To identify the process inputs (X's) and outputs (Y's)","To prove statistically which X causes the defects","To set the control limits for the process"],answer:1,hint:"A map is a picture of the process, not a statistical test.",steps:[{title:"Key idea",body:"Mapping supplies information for later tools: inputs (X's), outputs (Y's), VA/NVA steps, data collection points."},{title:"Eliminate look-alikes",body:"Proof, capability and control limits all need data."}],final:"Mapping identifies X's and Y's → answer **B**",whyWrong:["Incorrect — capability is calculated from data, not from a map.","","Incorrect — proof of cause needs data analysis and hypothesis tests in Analyze.","Incorrect — control limits come from SPC charts in Control."],bookRef:"Book p. 100"},{id:"sv-2-556",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"What is the goal of classifying process steps as value-added or non-value-added?",options:["To remove unnecessary activity from the process","To decide the order of the steps on the map","To calculate the sigma level of each step","To decide which employees to move to other teams"],answer:0,hint:"Waste uses resources but adds no value.",steps:[{title:"Key idea",body:"The book: the goal of the VA/NVA test is to remove unnecessary activity."},{title:"Apply to the stem",body:"NVA steps are marked so that they can be removed or made as small as possible."}],final:"Goal = remove unnecessary activity → answer **A**",whyWrong:["","Incorrect — the map order comes from the real flow of work.","Incorrect — sigma level comes from defect data, not from the VA test.","Incorrect — the test is about activities, not about people."],bookRef:"Book p. 117"},{id:"sv-2-557",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Why does the book prefer the **team approach** to building a process map over interviewing people one at a time?",options:["It is faster, gives better quality and creates more buy-in","It needs no verification by walking the process","It produces a Level 3 map with performance data at once","It lets the manager approve the map without involving the workers"],answer:0,hint:"What do people gain by building the map together?",steps:[{title:"Key idea",body:"The book: the team approach is faster, gives better quality and more buy-in than one-to-one interviews."},{title:"Eliminate look-alikes",body:"It still needs walking, and it starts at Level 2, not Level 3."}],final:"Faster, better quality, more buy-in → answer **A**",whyWrong:["","Incorrect — even a team map must be verified by walking the process.","Incorrect — the team session produces a Level 2 map; data comes later.","Incorrect — the approach depends on involving the process members."],bookRef:"Book p. 107"},{id:"sv-2-558",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"When outputs are listed in a SIPOC, what should **every output** have, according to the book?",options:["A metric, a lower specification limit, a target and an upper specification limit","A control chart and a capability index","A named supplier and a cost per unit","A decision diamond and a process owner"],answer:0,hint:"Outputs must be measurable against the customer's requirement.",steps:[{title:"Key idea",body:"Every output should have a metric, LSL, target and USL."},{title:"Apply to the stem",body:"This turns a customer requirement into something the team can measure."}],final:"Output → metric, LSL, target, USL → answer **A**",whyWrong:["","Incorrect — control charts and capability come later, from data.","Incorrect — suppliers belong to inputs, and cost per unit is not required.","Incorrect — decisions belong on a detailed map, not a SIPOC."],bookRef:"Book p. 112"},{id:"sv-2-559",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"In a value stream map data box, what does **uptime** describe?",options:["The number of items waiting in front of the step","The time one item spends being processed at the step","The share of the available working time that the step is actually able to run","The number of breaks taken during a shift"],answer:2,hint:"Uptime is written as a fraction such as 0.90.",steps:[{title:"Key idea",body:"Uptime is the fraction of time the step is running; it reduces the available time."},{title:"Eliminate look-alikes",body:"Queue, cycle time and breaks are other fields in the data box."}],final:"Uptime = fraction of time the step can run → answer **C**",whyWrong:["Incorrect — that is the queue (inventory).","Incorrect — that is the cycle time (C/T).","","Incorrect — breaks are subtracted from the shift; uptime is a separate fraction."],bookRef:"Book p. 105"},{id:"sv-2-560",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"On a value stream map, what does an **inventory triangle** between two steps show?",options:["Information sent from production control","A step that adds value to the product","A decision with a Yes and a No path","Work waiting in a queue between the steps"],answer:3,hint:"VSM icons: boxes for steps, triangles between them.",steps:[{title:"Key idea",body:"The triangle shows inventory: items waiting between steps."},{title:"Apply to the stem",body:"Large triangles point to long queues and possible bottlenecks."}],final:"Triangle = inventory / queue → answer **D**",whyWrong:["Incorrect — information flow is shown with arrows at the top of the map.","Incorrect — value-adding work sits in the process boxes, not in the triangles.","Incorrect — decisions are diamonds on a process map.",""],bookRef:"Syllabus 2.1.2"},{id:"sv-2-561",phase:2,topic:"2.1.2",qtype:"concept",difficulty:3,stem:"How is the queue in a value stream map data box turned into **days of work waiting**?",options:["By multiplying the queue by the uptime of the step","By multiplying the queue by the cycle time and dividing by the available working time per day","By dividing the cycle time by the queue","By dividing the queue by the number of operators on the shift"],answer:1,hint:"Work waiting = items × time per item, compared with time available each day.",steps:[{title:"Key idea",body:"Days in queue = (queue × cycle time) ÷ available time per day."},{title:"Apply to the stem",body:"Available time = (shift − breaks) × uptime."},{title:"Eliminate look-alikes",body:"Head count, uptime alone and inverted ratios do not give days."}],final:"Queue × C/T ÷ available time → answer **B**",whyWrong:["Incorrect — uptime only adjusts the available time; it does not convert items into days.","","Incorrect — this inverts the relationship and gives no time in days.","Incorrect — headcount alone ignores how long each item takes."],bookRef:"Book p. 105"},{id:"sv-2-562",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"How is a draft process map **verified**, according to the book?",options:["By asking the sponsor to sign it off","By checking that every step has a cycle time","By walking the process with the people who do the work","By comparing it with the written procedure"],answer:2,hint:"Only one option checks the map against reality.",steps:[{title:"Key idea",body:"The team consolidates a Level 2 map and then verifies it by walking the process."},{title:"Eliminate look-alikes",body:"Procedures and sign-offs reflect the 'think' view; walking reveals the 'actually is' view."}],final:"Walk the process → answer **C**",whyWrong:["Incorrect — sign-off approves the map but does not check it against reality.","Incorrect — performance data is added at Level 3; it does not verify the flow.","","Incorrect — the written procedure shows what people think the process is, not what it is."],bookRef:"Book p. 107"},{id:"sv-2-563",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"What does the **RUMBA** test check?",options:["Whether a project should be selected","Whether a measurement system is adequate","Whether a process step adds value","Whether a customer requirement is valid"],answer:3,hint:"RUMBA is used while adding requirements to a SIPOC.",steps:[{title:"Key idea",body:"RUMBA — Reasonable, Understandable, Measurable, Believable, Achievable — tests whether a requirement is valid."},{title:"Apply to the stem",body:"If a requirement fails, the team negotiates with the customer."}],final:"RUMBA validates requirements → answer **D**",whyWrong:["Incorrect — project selection uses other criteria and tools.","Incorrect — measurement systems are checked with MSA (Gage R&R).","Incorrect — the VA test uses form/fit/function and customer willingness to pay.",""],bookRef:"Book p. 112"},{id:"sv-2-564",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Whose view of the process does a **Level 2** process map show?",options:["The supplier's","The senior manager's","The worker's","The customer's"],answer:2,hint:"Each level matches one audience.",steps:[{title:"Key idea",body:"Level 1 = management view, Level 2 = worker view, Level 3 = improvement view."},{title:"Apply to the stem",body:"Level 2 shows the major steps as the worker does them, with decisions."}],final:"Level 2 = worker view → answer **C**",whyWrong:["Incorrect — suppliers appear in a SIPOC, not as a map level.","Incorrect — the management view is the Level 1 macro map.","","Incorrect — none of the three levels is described as the customer's view."],bookRef:"Book p. 102"},{id:"sv-2-565",phase:2,topic:"2.1.2",qtype:"concept",difficulty:3,stem:"How can the spreadsheet output of a detailed **Level 3** map be used later in the Measure phase?",options:["By using it as proof that the listed inputs cause the defects","By feeding it directly into a cause-and-effect (X-Y) matrix and an FMEA","By using it as the control chart for the Control phase","By sending it to the customer as the agreed specification"],answer:1,hint:"The Level 3 map lists inputs, specs and performance for each step.",steps:[{title:"Key idea",body:"The book notes the level-3 spreadsheet can be fed directly into a C&E matrix and an FMEA."},{title:"Eliminate look-alikes",body:"It neither proves cause nor serves as a control chart or specification."}],final:"Level 3 → X-Y matrix and FMEA → answer **B**",whyWrong:["Incorrect — a map lists candidate X's; it does not prove cause.","","Incorrect — control charts need data plotted over time in Control.","Incorrect — specifications are agreed through requirements, not a map spreadsheet."],bookRef:"Book p. 116"},{id:"sv-2-566",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"In the book's preferred way of describing a process, what is the role of the **operational description**?",options:["To list the suppliers of the process","To give the process a generic name","To describe the purpose of the process","To show the workflow of the process"],answer:2,hint:"Three parts: name, map, description — each has one job.",steps:[{title:"Key idea",body:"Generic name + process map (workflow) + operational description (purpose)."},{title:"Apply to the stem",body:"The operational description says what the process is for."}],final:"Operational description = purpose → answer **C**",whyWrong:["Incorrect — suppliers are captured in a SIPOC.","Incorrect — naming is a separate first part of the description.","","Incorrect — the workflow is shown by the process map."],bookRef:"Book p. 99"},{id:"sv-2-567",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"How are non-value-added steps that **cannot be removed**, such as data required by government regulation, handled?",options:["By reclassifying them as value-added","By keeping them but making them as small as possible","By leaving them off the process map","By moving them to the end of the process"],answer:1,hint:"Some waste is unavoidable; what does the book say to do with it?",steps:[{title:"Key idea",body:"Some NVA steps must stay, for planning or regulation."},{title:"Apply to the stem",body:"They are kept but made as small as possible."}],final:"Keep, but minimise → answer **B**",whyWrong:["Incorrect — being required does not make a step value-added.","","Incorrect — the map must show the process as it actually is.","Incorrect — moving a step does not reduce its waste."],bookRef:"Book p. 117"},{id:"sv-2-568",phase:2,topic:"2.1.2",qtype:"concept",difficulty:3,stem:"A team lists the outputs of a hardware-repair process. Which SIPOC entry is an **output requirement** rather than an output?",options:["Repaired unit returned within 3 working days","Replacement part request","Repair job closure record","Repaired customer router"],answer:0,hint:"An output is a thing produced; a requirement is a measurable condition on it.",steps:[{title:"Key idea",body:"SIPOC lists outputs and then the requirements the customers place on them."},{title:"Apply to the stem",body:"'Within 3 working days' is a measurable condition — a requirement."},{title:"Eliminate look-alikes",body:"The other three are things the process produces."}],final:"Requirement = measurable condition on an output → answer **A**",whyWrong:["","Incorrect — a part request is an output sent to a supplier step.","Incorrect — the closure record is an output (a document produced).","Incorrect — the repaired router is an output itself."],bookRef:"Book pp. 111–112"},{id:"sv-2-569",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which statement about a **SIPOC** is CORRECT?",options:["Requirements are added only after the value stream map is finished","Requirements are left out, because a SIPOC is a high-level map","Requirements are written only on the supplier side, as input specifications","Requirements can be added on both sides: on the inputs and on the outputs"],answer:3,hint:"The SIPOC answers 'what specs are on the inputs?' and 'what do the customers require?'.",steps:[{title:"Key idea",body:"The book: requirements can be added on both sides of the SIPOC."},{title:"Apply to the stem",body:"Input requirements on the supplier side, customer requirements on the output side."}],final:"Requirements on both sides → answer **D**",whyWrong:["Incorrect — requirements are captured while the SIPOC is built, early in mapping.","Incorrect — being high-level does not remove the requirements columns.","Incorrect — customer (output) requirements are a core part of the SIPOC.",""],bookRef:"Book p. 111"},{id:"sv-2-570",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Which statement about a **linear flow map** is CORRECT?",options:["It shows one lane for each department that performs the steps","It shows the steps in sequence from left to right, and most people start mapping with it","It shows suppliers and customers with their requirements","It shows queue sizes and cycle times for each major step"],answer:1,hint:"Four map types: linear, swim lane, SIPOC, VSM.",steps:[{title:"Key idea",body:"A linear flow map lists the steps in order, left to right; it is where most people start."},{title:"Eliminate look-alikes",body:"Lanes, queue data and supplier/customer columns belong to the other three map types."}],final:"Linear map = steps left to right → answer **B**",whyWrong:["Incorrect — that is a swim lane (deployment) map.","","Incorrect — that is a SIPOC.","Incorrect — that is a value stream map."],bookRef:"Book p. 103"},{id:"sv-2-571",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which statement about the difference between a value stream map and a basic process map is TRUE?",options:["A basic process map is better for finding bottlenecks, because it shows decisions","A value stream map shows fewer steps, because it replaces the macro map","A basic process map always includes the cycle time of each step","A value stream map adds timing and queue data, which makes it very good for finding bottlenecks"],answer:3,hint:"Which map carries speed and queue data?",steps:[{title:"Key idea",body:"The VSM shows speed, queue sizes and performance per step — ideal for bottlenecks."},{title:"Eliminate look-alikes",body:"A basic map shows the flow and decisions but not the time and queues."}],final:"VSM = timing + queues → bottlenecks → answer **D**",whyWrong:["Incorrect — decisions alone do not show where work piles up.","Incorrect — the VSM is not a substitute for the macro map; it adds data.","Incorrect — cycle times appear on a VSM or a Level 3 map, not on a basic map.",""],bookRef:"Book p. 105"},{id:"sv-2-572",phase:2,topic:"2.1.2",qtype:"concept",difficulty:3,stem:"Which statement about the **available time** used in a value stream map is CORRECT?",options:["It is the uptime minus the cycle time","It is the full shift time, because breaks are part of the working day","It is the cycle time multiplied by the queue","It is the shift time minus breaks, reduced by the uptime of the step"],answer:3,hint:"Book example: 8 h shift, 0.5 h breaks, uptime 0.90.",steps:[{title:"Key idea",body:"Available time = (shift − breaks) × uptime."},{title:"Apply to the stem",body:"It is the time the step can really work each day; the queue is compared against it."}],final:"Available = (shift − breaks) × uptime → answer **D**",whyWrong:["Incorrect — uptime is a fraction and cannot be combined with a cycle time this way.","Incorrect — breaks must be taken out first.","Incorrect — queue × cycle time is the work waiting, not the time available.",""],bookRef:"Book p. 105"},{id:"sv-2-573",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Which statement about the **'should be'** view of a process is CORRECT?",options:["It is the result of the improvement project","It is found by walking the process","It is the same as what people think the process is","It is drawn first, before the actual process is mapped"],answer:0,hint:"Three views: think, actually is, should be.",steps:[{title:"Key idea",body:"The book: the 'should be' view is the result of your project."},{title:"Eliminate look-alikes",body:"Walking gives the actual view; 'think' is the belief before mapping."}],final:"Should be = project result → answer **A**",whyWrong:["","Incorrect — walking reveals the 'actually is' view.","Incorrect — the 'think' view is a separate, usually inaccurate view.","Incorrect — the actual process is mapped first so the gap can be seen."],bookRef:"Book p. 100"},{id:"sv-2-574",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which statement about building a **Level 1 macro map** is CORRECT?",options:["It should include the yields of each major step","It should include only the steps where the problem occurs","It should include every decision in the process","It should include at least one step before and one step after the area that contains the problem"],answer:3,hint:"The macro map gives the big picture around the problem.",steps:[{title:"Key idea",body:"Add at least one step before and one after the area containing your problem."},{title:"Apply to the stem",body:"This shows where the problem sits in the wider flow."}],final:"Add a step before and after → answer **D**",whyWrong:["Incorrect — yields are performance data for a Level 3 map.","Incorrect — the book asks for context on both sides of the problem area.","Incorrect — detailed decisions belong on a Level 2 map.",""],bookRef:"Book p. 102"},{id:"sv-2-575",phase:2,topic:"2.1.2",qtype:"concept",difficulty:3,stem:"Which statement about **rolled throughput yield (RTY)** on a value stream map is TRUE?",options:["It is the average first-pass yield of the steps, and the step with the longest queue is the quality bottleneck","It is the share of steps that have no defects at all","It is the yield of the final step only, because only the last step reaches the customer","It is the chance that an item passes every step first time, and the step with the lowest yield is the quality bottleneck"],answer:3,hint:"RTY combines the first-pass yields of all steps.",steps:[{title:"Key idea",body:"RTY = product of the first-pass yields; it is the share of items passing all steps first time."},{title:"Apply to the stem",body:"The step with the lowest yield drags RTY down most: the quality bottleneck."}],final:"RTY = all steps first time; lowest yield = quality bottleneck → answer **D**",whyWrong:["Incorrect — RTY multiplies yields, and the quality bottleneck is the lowest-yield step.","Incorrect — RTY is about items passing all steps, not a count of steps.","Incorrect — every step's first-pass yield counts, not only the last.",""],bookRef:"Book p. 105"},{id:"sv-2-576",phase:2,topic:"2.1.2",qtype:"concept",difficulty:3,stem:"Which statement about **inspection and review** steps on a process map is CORRECT?",options:["They are value-added because they protect the customer","They are left off the map because they are not part of the work","They are non-value-added even when the procedure requires them","They are value-added when a manager performs them"],answer:2,hint:"Apply form/fit/function and 'would the customer pay?'.",steps:[{title:"Key idea",body:"Reviews and inspections do not change the item, and the customer does not pay for them."},{title:"Apply to the stem",body:"They are NVA; if they must stay, keep them small."}],final:"Inspection/review = NVA → answer **C**",whyWrong:["Incorrect — the customer is not paying for checking; it does not change form, fit or function.","Incorrect — the map must show every step that actually happens.","","Incorrect — who performs a step does not change whether it adds value."],trap:"'Required' does not mean 'value-added'.",bookRef:"Book p. 117"},{id:"sv-2-577",phase:2,topic:"2.1.2",qtype:"concept",difficulty:1,stem:"Which statement about process mapping is TRUE according to the book?",options:["It is done only by the process owner","It is the last activity of the Analyze phase","It is the first activity of the Measure phase","It is done only after the data has been collected"],answer:2,hint:"Mapping tells the team where to collect data.",steps:[{title:"Key idea",body:"The book: process mapping is the first activity of the Measure phase."},{title:"Eliminate look-alikes",body:"It precedes data collection and is done as a team."}],final:"First activity of Measure → answer **C**",whyWrong:["Incorrect — the book prefers a team approach with the process members.","Incorrect — mapping comes much earlier, before data collection.","","Incorrect — mapping shows where to collect data, so it comes first."],bookRef:"Book p. 99"},{id:"sv-2-578",phase:2,topic:"2.1.2",qtype:"concept",difficulty:2,stem:"Which statement about **push and pull** on a value stream map is TRUE?",options:["Push and pull describe the direction of information flow only, not material flow","Push and pull both mean that work waits in a supermarket until the customer orders","With push, the next step signals when it needs work; with pull, work is sent whether or not it is ready","With push, work is sent to the next step whether or not it is ready; with pull, the next step signals when it needs work"],answer:3,hint:"Who triggers the movement of work?",steps:[{title:"Key idea",body:"Push: the upstream step sends work regardless. Pull: the downstream step signals its need (kanban, supermarket)."},{title:"Apply to the stem",body:"Push arrows usually sit next to large inventory triangles."}],final:"Push = sent regardless; pull = signalled → answer **D**",whyWrong:["Incorrect — push and pull describe how the work itself moves.","Incorrect — supermarkets and kanban belong to pull only.","Incorrect — this swaps the two definitions.",""],bookRef:"Syllabus 2.1.2"},{id:"sv-2-579",phase:2,topic:"2.1.2",qtype:"statements",difficulty:1,stem:`Consider these statements about standard process-map symbols:

1. A rectangle shows an activity, and its text starts with a verb.
2. A diamond shows a decision with only Yes and No paths.
3. A parallelogram shows the start or end of the process.
4. An ellipse shows data used by the process.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Rectangle = activity, diamond = decision, parallelogram = data, ellipse = start/end.",steps:[{title:"Key idea",body:"Check each statement against the symbol table."},{title:"Apply to the stem",body:"1 and 2 are true; 3 and 4 swap parallelogram and ellipse."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Statement 3 is false — the start and end are ellipses; a parallelogram is data.","Statements 3 and 4 swap the meanings of the parallelogram and the ellipse.","Statement 4 is false — an ellipse is start/end; data is a parallelogram."],bookRef:"Book p. 101"},{id:"sv-2-580",phase:2,topic:"2.1.2",qtype:"statements",difficulty:2,stem:`Consider these statements about the three levels of process map:

1. A Level 3 map shows the least detail of the three.
2. A Level 2 map shows the major steps as the worker does them, including decisions.
3. A Level 3 map can include yields, cycle times and DPU.
4. A Level 1 map is the main map for detailed improvement work.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Level 1 macro/management, Level 2 worker, Level 3 micro/improvement with data.",steps:[{title:"Key idea",body:"Detail grows from Level 1 to Level 3."},{title:"Apply to the stem",body:"2 and 3 are true; 1 and 4 reverse the levels."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Statement 1 is false — Level 3 is the most detailed map.","","Statement 4 is false — Level 1 is the management view with minimal detail.","Statements 1 and 4 both reverse the roles of Level 1 and Level 3."],bookRef:"Book pp. 102–103"},{id:"sv-2-581",phase:2,topic:"2.1.2",qtype:"statements",difficulty:3,stem:`Consider these statements about a SIPOC:

1. It is built starting with the suppliers, then the inputs.
2. Its process column holds a detailed Level 3 map.
3. Requirements can be added on both the input and output sides.
4. It helps the team identify the true customers of the process.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"SIPOC = high-level, built from outputs/customers back to inputs/suppliers.",steps:[{title:"Key idea",body:"Preferred order: outputs, customers, requirements, inputs, suppliers, input requirements."},{title:"Apply to the stem",body:"3 and 4 are true; 1 has the wrong order, 2 the wrong level."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Statement 1 is false — the preferred order starts with outputs and customers.","Statement 2 is false — the P column is a high-level map of about 4–8 steps.","","Statement 1 is false — the build order starts from outputs, not suppliers."],bookRef:"Book p. 111"},{id:"sv-2-582",phase:2,topic:"2.1.2",qtype:"statements",difficulty:2,stem:`Consider these statements about swim lane (deployment) maps:

1. Each lane holds the steps done by one person or department.
2. The lanes show how long each value-added step takes.
3. Adding more lane crossings reduces queues.
4. Each lane crossing is a supplier–customer hand-off.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Swim lanes = who does each step; crossings = hand-offs.",steps:[{title:"Key idea",body:"A swim lane map shows responsibility; every crossing is a supplier–customer hand-off."},{title:"Apply to the stem",body:"1 and 4 are true; 2 confuses lanes with timing, 3 reverses the effect of hand-offs."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Statement 2 is false — lanes show who does the work, not how long it takes.","Statements 2 and 3 are false — lanes show ownership, and crossings create queues.","Statement 3 is false — hand-offs are where queues usually form.",""],bookRef:"Book p. 103"},{id:"sv-2-583",phase:2,topic:"2.1.2",qtype:"statements",difficulty:2,stem:`Consider these statements about value stream maps:

1. They show the queue sizes in front of each major step.
2. They are very good for finding bottlenecks.
3. They remove the need to walk the process.
4. They show only the value-added steps.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"VSM = speed, queues, performance per step.",steps:[{title:"Key idea",body:"A VSM adds queues and timing so bottlenecks stand out."},{title:"Apply to the stem",body:"1 and 2 are true; a VSM still needs walking and shows NVA waiting too."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Statement 3 is false — any map must still be checked against the real process.","Statements 3 and 4 are false — walking is still needed, and NVA waiting is a key part of a VSM.","Statement 4 is false — the VSM shows waiting and queues, which are non-value-added."],bookRef:"Book p. 105"},{id:"sv-2-584",phase:2,topic:"2.1.2",qtype:"statements",difficulty:3,stem:`Consider these statements about value-added analysis:

1. A step required by government regulation is value-added.
2. A step whose name starts with 're', such as rework, is very likely waste.
3. A non-value-added step can be marked on the map with a red X.
4. A step is value-added if it uses people or machine time.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"VA = changes form/fit/function AND the customer would pay.",steps:[{title:"Key idea",body:"Apply the two VA questions to each statement."},{title:"Apply to the stem",body:"2 and 3 are true; 1 and 4 confuse 'required' or 'uses resources' with value."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Statement 1 is false — a required step can still be NVA; it is kept but minimised.","","Statement 4 is false — using resources without creating value is exactly what waste is.","Statements 1 and 4 are false — being required or using resources does not make a step VA."],bookRef:"Book p. 117"},{id:"sv-2-585",phase:2,topic:"2.1.2",qtype:"statements",difficulty:2,stem:`Consider these statements about the book's team approach to mapping:

1. Interviewing people one by one gives more buy-in than a team session.
2. Each post-it records the task's work time plus its waiting time.
3. The post-its are consolidated into a Level 2 map at once.
4. The map is then verified by walking the process.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Team approach: macro map → sheets → post-its (work time only) → Level 2 → walk.",steps:[{title:"Key idea",body:"Recall the book's team approach and its advantages."},{title:"Apply to the stem",body:"3 and 4 are true; 1 reverses the buy-in benefit, 2 adds waiting time."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Statement 1 is false — the team approach gives more buy-in than interviews.","Statement 2 is false — post-its show actual work time only, no waiting time.","","Statement 1 is false — interviews give less buy-in, not more."],bookRef:"Book p. 107"},{id:"sv-2-586",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A swim lane map is also called a [?] map, because it shows how the work is deployed across people or departments.`,options:["Deployment","Linear","Macro","Micro"],answer:0,hint:"The lanes show who the work is deployed to.",steps:[{title:"Key idea",body:"Swim lane map = deployment map: one lane per person or department."},{title:"Eliminate look-alikes",body:"Linear, macro and micro name other map types or levels."}],final:"Deployment map → answer **A**",whyWrong:["","Incorrect — a linear flow map has no lanes; it lists steps left to right.","Incorrect — macro is Level 1, a level of detail, not a lane map.","Incorrect — micro is Level 3, a level of detail, not a lane map."],bookRef:"Book p. 103"},{id:"sv-2-587",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

A Level 3 map is the [?] view of the process, because it adds performance data such as yields, cycle times and DPU.`,options:["Improvement","Management","Supplier","Worker"],answer:0,hint:"Each level has a named view: management, worker, improvement.",steps:[{title:"Key idea",body:"Level 1 management, Level 2 worker, Level 3 improvement (micro)."},{title:"Apply to the stem",body:"Performance data is what the improvement work needs."}],final:"Improvement view → answer **A**",whyWrong:["","Incorrect — the management view is Level 1.","Incorrect — suppliers belong to a SIPOC, not a map level.","Incorrect — the worker view is Level 2."],bookRef:"Book p. 102"},{id:"sv-2-588",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:3,stem:`Identify the missing word in the following sentence.

In the book's preferred order for building a SIPOC, the last element to be identified is the [?] requirements.`,options:["Customer","Input","Output","Supplier"],answer:1,hint:"Outputs → customers → customer requirements → inputs → suppliers → ?",steps:[{title:"Key idea",body:"The sixth and last item is the input requirements."},{title:"Apply to the stem",body:"The team first fixes what customers need, then what the inputs must meet."}],final:"Input requirements last → answer **B**",whyWrong:["Incorrect — customer requirements are third, straight after the customers.","","Incorrect — the order starts with outputs; their requirements are the customer requirements.","Incorrect — suppliers are fifth; the last item is the requirements placed on their inputs."],bookRef:"Book p. 111"},{id:"sv-2-589",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The book's value-added test asks whether the activity changes the form, fit or [?] of the work item, and whether the customer is willing to pay for it.`,options:["Cost","Function","Price","Quality"],answer:1,hint:"The test has three words: form, fit and …",steps:[{title:"Key idea",body:"Form, fit or function — plus 'would the customer pay?'."},{title:"Eliminate look-alikes",body:"Cost, price and quality are not the words the book uses."}],final:"Form, fit or function → answer **B**",whyWrong:["Incorrect — cost rises with any activity, value-added or not.","","Incorrect — price links to the second question (willing to pay), not the first.","Incorrect — quality is not one of the three words in the test."],bookRef:"Book p. 117"},{id:"sv-2-590",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Each time work crosses from one lane to another on a swim lane map, there is a supplier–customer [?].`,options:["Decision","Hand-off","Inspection","Rework"],answer:1,hint:"A lane crossing passes the work to someone else.",steps:[{title:"Key idea",body:"The book: every lane crossing is a supplier–customer hand-off."},{title:"Apply to the stem",body:"Hand-offs are where bottlenecks and queues usually form."}],final:"Lane crossing = hand-off → answer **B**",whyWrong:["Incorrect — decisions are diamonds and can sit inside one lane.","","Incorrect — a lane crossing passes work on; it does not check it.","Incorrect — rework is a loop back, not the crossing itself."],bookRef:"Book p. 103"},{id:"sv-2-591",phase:2,topic:"2.1.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

A Level 1 macro map usually shows between four and [?] major steps.`,options:["eight","fifteen","twelve","twenty"],answer:0,hint:"The macro map keeps detail to a minimum.",steps:[{title:"Key idea",body:"The book: a Level 1 map usually has 4–8 steps."},{title:"Apply to the stem",body:"The SIPOC's P column uses the same 4–8 step range."}],final:"4–8 steps → answer **A**",whyWrong:["","Incorrect — fifteen steps is far more than a minimal-detail macro view.","Incorrect — twelve steps is too many for the management view.","Incorrect — twenty steps is Level 2 or Level 3 detail."],bookRef:"Book p. 102"},{id:"sv-2-592",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the four types of process map described in the book?",options:["Cause-and-effect (fishbone) diagram","Value stream map","Swim lane map","SIPOC"],answer:0,hint:"Four types: linear flow, swim lane, SIPOC, value stream map.",steps:[{title:"Key idea",body:"The book lists linear flow, swim lane, SIPOC and value stream maps."},{title:"Apply to the stem",body:"A fishbone lists possible causes of an effect; it does not map the flow of work."}],final:"Fishbone is not a process map → answer **A**",whyWrong:["","Incorrect — the value stream map is one of the four types.","Incorrect — the swim lane map is one of the four types.","Incorrect — SIPOC is one of the four types."],bookRef:"Book p. 103"},{id:"sv-2-593",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:3,stem:"Process mapping gives the team all of the following EXCEPT:",options:["The value-added and non-value-added steps","Statistical proof of which inputs cause the defects","The points where data such as cycle time and defects can be collected","The decision points and quick fixes in the process"],answer:1,hint:"A map is a picture of the work, not a data analysis.",steps:[{title:"Key idea",body:"Mapping supplies X's, Y's, VA/NVA steps, data collection points, decisions and quick fixes."},{title:"Apply to the stem",body:"Proof that an X causes a defect needs data and tests in Analyze."}],final:"No statistical proof from a map → answer **B**",whyWrong:["Incorrect — mapping does show VA and NVA steps.","","Incorrect — mapping does show data collection points.","Incorrect — mapping does show decision points and quick fixes."],bookRef:"Book p. 100"},{id:"sv-2-594",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:2,stem:"A value stream map data box for a step records all of the following EXCEPT:",options:["The cycle time (C/T)","The shift length and break time","The uptime of the step","The customer requirements tested with RUMBA"],answer:3,hint:"Data boxes hold the operating data needed for timing.",steps:[{title:"Key idea",body:"Book example data box: queue, C/T, shift, breaks, uptime."},{title:"Apply to the stem",body:"RUMBA-tested requirements belong to the SIPOC, not a VSM data box."}],final:"Requirements are not in the data box → answer **D**",whyWrong:["Incorrect — cycle time is a standard data box field.","Incorrect — shift and breaks are recorded to work out available time.","Incorrect — uptime is a standard data box field.",""],bookRef:"Book p. 105"},{id:"sv-2-595",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:2,stem:"The book's team approach to building a process map includes all of the following EXCEPT:",options:["Taping one sheet on the wall for each macro step","Writing one task per post-it","Agreeing the macro map with the team","Interviewing each process member separately and merging the notes"],answer:3,hint:"The team approach is an alternative to one-to-one interviews.",steps:[{title:"Key idea",body:"Team approach: agree the macro map, one sheet per macro step, one task per post-it, consolidate, walk."},{title:"Apply to the stem",body:"Separate interviews are the slower method it replaces."}],final:"Interviews are not the team approach → answer **D**",whyWrong:["Incorrect — one sheet per macro step is part of the method.","Incorrect — one task per post-it is part of the method.","Incorrect — the team agrees the macro map first.",""],bookRef:"Book p. 107"},{id:"sv-2-596",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:2,stem:"For a prepaid top-up process, each of the following would be listed as an **input** in the SIPOC EXCEPT:",options:["The top-up confirmation SMS","The customer's mobile number","The customer's payment details","The top-up amount chosen"],answer:0,hint:"Inputs go into the process; outputs come out of it.",steps:[{title:"Key idea",body:"Inputs are what the process uses; outputs are what it produces for its customers."},{title:"Apply to the stem",body:"The confirmation SMS is produced by the process — an output."}],final:"Confirmation SMS is an output → answer **A**",whyWrong:["","Incorrect — the mobile number is information the process needs: an input.","Incorrect — payment details are an input supplied by the customer or bank.","Incorrect — the chosen amount is an input to the top-up."],bookRef:"Book p. 111"},{id:"sv-2-597",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:2,stem:"A Level 1 macro map shows all of the following EXCEPT:",options:["Where the process fits in the bigger picture","The cycle time and yield of each task","A step before and a step after the problem area","Only the major steps of the process"],answer:1,hint:"The macro map keeps detail to a minimum.",steps:[{title:"Key idea",body:"Level 1: major steps, minimal detail, big picture, 4–8 steps."},{title:"Apply to the stem",body:"Cycle times and yields are performance data for a Level 3 map."}],final:"No performance data on Level 1 → answer **B**",whyWrong:["Incorrect — showing the big picture is its main purpose.","","Incorrect — the book asks for this context around the problem.","Incorrect — the macro map does show only the major steps."],bookRef:"Book pp. 102–103"},{id:"sv-2-598",phase:2,topic:"2.1.2",qtype:"not-except",difficulty:1,stem:"Each symbol below is matched with its correct meaning EXCEPT:",options:["Ellipse — start or end","Parallelogram — decision","Arrow — direction of flow","Rectangle — activity"],answer:1,hint:"Recall the six symbols in the book's table.",steps:[{title:"Key idea",body:"A parallelogram is data; a decision is a diamond."},{title:"Apply to the stem",body:"The other three pairs match the book's table."}],final:"Parallelogram = data, not decision → answer **B**",whyWrong:["Incorrect — an ellipse is the start or end.","","Incorrect — an arrow is the direction of flow.","Incorrect — a rectangle is an activity."],bookRef:"Book p. 101"},{id:"sv-2-599",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:2,stem:"Before any detailed mapping, the sponsor of an invoice-dispute project wants the team to agree on **one page** where the process starts and ends, who supplies what goes in, what comes out and who receives it. Which tool should the team use?",options:["Level 3 micro map","Value stream map","Swim lane map","SIPOC"],answer:3,hint:"Suppliers, inputs, process, outputs, customers on one page.",steps:[{title:"Key idea",body:"A SIPOC sets the boundaries and lists suppliers, inputs, a 4–8 step process, outputs and customers."},{title:"Eliminate look-alikes",body:"Micro, VSM and swim lane maps add detail, timing or ownership instead."}],final:"Scope on one page → SIPOC → answer **D**",whyWrong:["Incorrect — a micro map is the most detailed view, not a one-page scope.","Incorrect — a VSM adds timing and queues; it is not the scoping tool.","Incorrect — a swim lane map shows who does each step, not suppliers and customers.",""],bookRef:"Book p. 111"},{id:"sv-2-600",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:2,stem:"A Black Belt has a worker-level map of a SIM-swap process. To prepare the FMEA she now needs each task shown with its **yield, cycle time and defects per unit**. Which map should she build next?",options:["A SIPOC","A linear flow map of the major steps","A Level 1 macro map","A Level 3 micro map"],answer:3,hint:"Which level adds performance data?",steps:[{title:"Key idea",body:"Level 3 (micro, improvement view) adds yields, cycle times, VA/NVA time, defects, DPU and RTY."},{title:"Apply to the stem",body:"She already has Level 2, so the next step down is Level 3."}],final:"Performance data per task → Level 3 → answer **D**",whyWrong:["Incorrect — a SIPOC is a high-level summary without task data.","Incorrect — a map of the major steps lacks the performance data she needs.","Incorrect — the macro map has less detail than her current map.",""],bookRef:"Book pp. 102–103"},{id:"sv-2-601",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:3,stem:"A data-centre change process was first drawn by the process owner from the written procedure. When the team walked the process, it found an unofficial second approval loop and two manual spreadsheet steps. What does this BEST illustrate?",options:["The gap between the actual process and what it should be","The gap between what people think the process is and what it actually is","The difference between a Level 1 and a Level 2 map","The difference between a SIPOC and a value stream map"],answer:1,hint:"Three views: think, actually is, should be.",steps:[{title:"Key idea",body:"The procedure shows what people think; walking shows what actually happens."},{title:"Apply to the stem",body:"Hidden loops and manual steps are typical of the real process being bigger than believed."}],final:"Think vs actually is → answer **B**",whyWrong:["Incorrect — the 'should be' is the future target; the team found hidden current steps.","","Incorrect — the change is about hidden steps, not about the level of detail.","Incorrect — no map type was changed; the same process was simply observed."],bookRef:"Book p. 100"},{id:"sv-2-602",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:1,stem:"A router assembly plant wants to find which station limits output. It needs a picture showing the **cycle time** of each station and the **number of boards waiting** between stations. Which tool fits BEST?",options:["Value stream map","Swim lane map","SIPOC","Cause-and-effect diagram"],answer:0,hint:"Cycle times + inventory between steps → which map?",steps:[{title:"Key idea",body:"A VSM shows speed, queues and performance per step: very good for finding bottlenecks."},{title:"Eliminate look-alikes",body:"SIPOC, swim lane and fishbone do not carry queue and time data."}],final:"Bottleneck with queues and C/T → VSM → answer **A**",whyWrong:["","Incorrect — a swim lane map shows who does each step, not queues.","Incorrect — a SIPOC scopes the process; it shows no cycle times or queues.","Incorrect — a fishbone lists possible causes, not flow data."],bookRef:"Book p. 105"},{id:"sv-2-603",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:3,stem:"In a PCB plant, a forklift moves pallets of finished boards from the store to the packing line. The boards are not changed, and the customer does not pay for the move. How should the team classify this step on its map?",options:["Value-added, because it uses a skilled driver and equipment","Non-value-added, because it does not change form, fit or function and the customer would not pay for it","Value-added, because the boards cannot be packed without it","Non-value-added only if the move takes longer than the packing step"],answer:1,hint:"Apply the two value-added questions.",steps:[{title:"Key idea",body:"VA test: changes form, fit or function, and customer willing to pay."},{title:"Apply to the stem",body:"Moving boards changes neither, so it is NVA — keep it as small as possible."}],final:"Transport = NVA → answer **B**",whyWrong:["Incorrect — using resources without changing the item is waste.","","Incorrect — being necessary for the flow does not make a step value-added.","Incorrect — the VA test does not depend on how long a step takes."],bookRef:"Book p. 117"},{id:"sv-2-604",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:2,stem:"To map a billing-correction process, a Black Belt spent three weeks interviewing six staff one at a time. Their accounts conflict and staff do not accept the merged map. Which approach would the book have recommended?",options:["Building a value stream map first, then interviewing people again","Using the written procedure as the map, because it is the official view","Asking the most senior manager to draw the map alone","Building the map in one team session with post-its, then walking the process"],answer:3,hint:"Which method is faster with more buy-in?",steps:[{title:"Key idea",body:"The team approach is faster, better quality and gives more buy-in than interviews."},{title:"Apply to the stem",body:"Process members build it together on post-its; the team then walks the process to verify."}],final:"Team approach with post-its → answer **D**",whyWrong:["Incorrect — a VSM does not fix the lack of a shared, agreed map.","Incorrect — the procedure shows what people think, not the actual process.","Incorrect — one person's map gives no buy-in and misses hidden work.",""],bookRef:"Book p. 107"},{id:"sv-2-605",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:3,stem:"In a fault-repair process, the 'Log repair request' step produces a **repair ticket** that goes straight to the **field dispatcher**, who plans the engineer visit. In the SIPOC for 'Log repair request', who is the customer of this ticket?",options:["The engineer's manager, because they approve the visit","The end customer, because every SIPOC customer is external","The field dispatcher, who receives the output","The ticketing system, because it stores the ticket"],answer:2,hint:"In a SIPOC, the customer is whoever receives the output.",steps:[{title:"Key idea",body:"The book's pizza example names the cook as the customer of the order-taking process — an internal customer."},{title:"Apply to the stem",body:"Here the ticket goes to the dispatcher, so the dispatcher is the customer."}],final:"Receiver of the output = customer → answer **C**",whyWrong:["Incorrect — approval is not receipt of the output.","Incorrect — a SIPOC customer is whoever receives the output, often an internal next step.","","Incorrect — the system is a tool or input supplier, not the customer."],trap:"SIPOC customers can be internal next steps.",bookRef:"Book p. 111"},{id:"sv-2-606",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:2,stem:"An IT service-desk team has a verified Level 2 map. It wants a list of **candidate X's** to rate in the X-Y matrix. Where on the map should it look?",options:["At the inputs used at each step of the map","At the end ellipse only, where the output leaves","At the off-page connectors, which link pages","At the arrows, which show the direction of flow"],answer:0,hint:"Mapping gives process inputs (X's) and outputs (Y's).",steps:[{title:"Key idea",body:"The process map is one of the three sources of potential X's."},{title:"Apply to the stem",body:"Each step's inputs become candidate X's for the X-Y matrix."}],final:"Step inputs = candidate X's → answer **A**",whyWrong:["","Incorrect — the end point shows the output (Y), not the inputs.","Incorrect — connectors only link pages of the map.","Incorrect — arrows show flow direction, not variables."],bookRef:"Book pp. 100, 118"},{id:"sv-2-607",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:1,stem:'On a draft complaint-handling map, one rectangle simply says **"Customer complaint"**. What change should the Black Belt make?',options:["Reword it to start with a verb, such as 'Log customer complaint'","Redraw it as a diamond, because complaints need a decision","Redraw it as a parallelogram, because a complaint is data","Remove it, because complaints are non-value-added"],answer:0,hint:"What rule applies to the text inside a rectangle?",steps:[{title:"Key idea",body:"A rectangle is an activity, and its text starts with a verb."},{title:"Apply to the stem",body:"'Log customer complaint' says what is done; a bare noun does not."}],final:"Activity text starts with a verb → answer **A**",whyWrong:["","Incorrect — a diamond needs a Yes/No question, which this step is not.","Incorrect — the step is an activity done with the complaint, so it stays a rectangle.","Incorrect — the map must show every step that actually happens."],bookRef:"Book p. 101"},{id:"sv-2-608",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:2,stem:"A team presents a map of the fibre-installation process **after** its planned improvements: two approvals removed and work pulled from a small buffer. Which view of the process is this map?",options:["What it was before mapping","What people think it is","What it should be","What it actually is"],answer:2,hint:"Three views: think, actually is, should be.",steps:[{title:"Key idea",body:"The 'should be' view is the result of the project."},{title:"Apply to the stem",body:"A map with the planned changes in place is the 'should be'."}],final:"Future target = should be → answer **C**",whyWrong:["Incorrect — this is not one of the book's views and describes the past, not the target.","Incorrect — the 'think' view is the belief before mapping.","","Incorrect — the actual view is today's process, found by walking it."],bookRef:"Book p. 100"},{id:"sv-2-609",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:1,stem:"A small accounts-payable team new to mapping wants a simple first map of its invoice process. All steps happen inside one team and no timing data is needed yet. Which map type should it start with?",options:["A Level 3 micro map","A swim lane map","A linear flow map","A value stream map"],answer:2,hint:"Which map shows steps in sequence and is where most people start?",steps:[{title:"Key idea",body:"The linear flow map shows steps left to right; most people start here."},{title:"Eliminate look-alikes",body:"Lanes, timing data and micro detail are not needed for this first map."}],final:"Simple first map → linear flow → answer **C**",whyWrong:["Incorrect — a micro map adds performance data, more than a first map needs.","Incorrect — with one team there are no lanes to show.","","Incorrect — a VSM is for timing and queue data, not needed yet."],bookRef:"Book p. 103"},{id:"sv-2-610",phase:2,topic:"2.1.2",qtype:"scenario",difficulty:2,stem:"A new hire at a network operations centre needs a map of the outage-escalation process that shows the **order of tasks and the decisions** an engineer meets, but no timing or yield data. Which level of map fits?",options:["Level 1 (macro)","Level 2 (worker view)","Level 3 (micro)","SIPOC"],answer:1,hint:"Which level is the worker's view with decisions?",steps:[{title:"Key idea",body:"Level 2 shows the major steps as the worker does them, including decisions."},{title:"Eliminate look-alikes",body:"Level 1 is too coarse, Level 3 adds data, SIPOC has no decisions."}],final:"Tasks + decisions, no data → Level 2 → answer **B**",whyWrong:["Incorrect — the macro map shows only major steps without decisions.","","Incorrect — Level 3 adds timing and yield data, which are not needed.","Incorrect — a SIPOC is a high-level scope without decisions."],bookRef:"Book p. 102"},{id:"sv-2-611",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:3,stem:`To save time, a Black Belt builds the SIPOC for a corporate-mobile order **left to right**: first the suppliers, then the inputs, the process, the outputs and finally the customers.

Was this an appropriate action?`,options:["Yes, because the order of the letters in SIPOC is the order in which it is built","Yes, because suppliers must be known before any input can be listed","No, because the process column must be drawn before any other column","No, because the preferred order starts with outputs and customers so that the inputs serve what customers need"],answer:3,hint:"The SIPOC is built from the customer end backwards.",steps:[{title:"Key idea",body:"Preferred order: outputs, customers, customer requirements, inputs, suppliers, input requirements."},{title:"Apply to the stem",body:"Working left to right puts suppliers first, which is the reverse of the preferred order."}],final:"No — start from outputs and customers → answer **D**",whyWrong:["Incorrect — the acronym is not the build order; the book's preferred order starts with outputs.","Incorrect — inputs and suppliers come after the customer side is understood.","Incorrect — the preferred order starts with outputs, not the process.",""],bookRef:"Book p. 111"},{id:"sv-2-612",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:2,stem:`In a mapping session for an order-fulfilment process, the facilitator tells each process member to write **one task per post-it with the actual work time**, and to leave out the time the work spends waiting.

Was this an appropriate action?`,options:["Yes, because the post-its should capture each task's work time; waiting is not part of the task","Yes, because waiting time is not important in a process map","No, because waiting time must be added to each task so that the lead time is complete","No, because times should not be written down until the map is verified"],answer:0,hint:"What does the book say goes on each post-it?",steps:[{title:"Key idea",body:"Team approach: one task per post-it, with the actual work time (no waiting time)."},{title:"Eliminate look-alikes",body:"Waiting is important, but it is not task time; it is studied separately, e.g. on a VSM."}],final:"Yes — work time only on post-its → answer **A**",whyWrong:["","Incorrect — waiting matters a great deal; it is simply not task time.","Incorrect — the book asks for actual work time only, with no waiting time.","Incorrect — the book asks for the work time on the post-it during the session."],bookRef:"Book p. 107"},{id:"sv-2-613",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:3,stem:`All process members took part in a workshop that produced a Level 2 map of the porting process. The Black Belt therefore decides **not to walk the process** and starts data collection straight away.

Was this an appropriate action?`,options:["Yes, because a map built by the whole team is already verified","Yes, because walking the process is only needed for interview-based maps","No, because the map must still be verified by walking the process to find hidden steps","No, because data collection may only start after a value stream map is complete"],answer:2,hint:"What does the book say happens straight after the team consolidates the map?",steps:[{title:"Key idea",body:"The team approach ends with verifying the map by walking the process."},{title:"Apply to the stem",body:"Hidden operations are common, so skipping the walk risks collecting data at the wrong points."}],final:"No — still walk the process → answer **C**",whyWrong:["Incorrect — a workshop shows what people think; it still needs checking against reality.","Incorrect — the book verifies the team map by walking too.","","Incorrect — a VSM is not a prerequisite for data collection."],bookRef:"Book p. 107"},{id:"sv-2-614",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:2,stem:'While classifying steps on a contract-handling map, the team finds **"Print and file a paper copy of each signed contract"**. No regulation or internal plan needs the paper copy, and the customer would not pay for it. What is the BEST action?',options:["Leave it unclassified until capability is known","Mark it non-value-added but keep it unchanged, because it is already in the procedure","Mark it value-added, because it protects the company","Mark it non-value-added and target it for removal"],answer:3,hint:"NVA steps without a planning or regulatory reason are removed.",steps:[{title:"Key idea",body:"Apply the VA test: no change to form, fit or function; customer would not pay → NVA."},{title:"Apply to the stem",body:"No regulation needs it, so the goal is to remove this unnecessary activity."}],final:"NVA, no requirement → remove → answer **D**",whyWrong:["Incorrect — the VA test needs no capability data.","Incorrect — only steps needed for planning or regulation are kept; this one is not.","Incorrect — protecting the company is not a change to form, fit or function.",""],bookRef:"Book p. 117"},{id:"sv-2-615",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:2,stem:`To avoid taking the team away from customer calls, a Black Belt maps the complaint-escalation process **alone at her desk** over a weekend, using her own experience.

Was this an appropriate action?`,options:["Yes, because one experienced person produces a more consistent map","Yes, because the map can be corrected later during Control","No, because a map should be built by the team: it is faster, better quality and gives more buy-in","No, because only the process owner is allowed to draw the map"],answer:2,hint:"Who should build the map, according to the book?",steps:[{title:"Key idea",body:"The book's preferred approach is a team approach with the process members."},{title:"Apply to the stem",body:"A single person's map reflects the 'think' view and creates no buy-in."}],final:"No — map as a team → answer **C**",whyWrong:["Incorrect — one person's map shows what they think the process is.","Incorrect — mapping is the first activity of Measure; errors would mislead data collection.","","Incorrect — the book prefers a team of process members, not one owner."],bookRef:"Book p. 107"},{id:"sv-2-616",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:3,stem:`The problem in a home-broadband process sits in the **activation** step. The Black Belt draws the Level 1 macro map with **activation only**, leaving out the steps before and after it.

Was this an appropriate action?`,options:["Yes, because the macro map should show only the problem area","Yes, because the steps before and after belong on the SIPOC","No, because the macro map should include every task inside activation","No, because the macro map should include at least one step before and one after the problem area"],answer:3,hint:"The macro map shows where the problem fits in the big picture.",steps:[{title:"Key idea",body:"The book: add at least one step before and one after the area containing the problem."},{title:"Eliminate look-alikes",body:"Task detail belongs at lower levels; context belongs on Level 1."}],final:"No — add a step before and after → answer **D**",whyWrong:["Incorrect — the book asks for context around the problem area.","Incorrect — the macro map itself needs the surrounding steps.","Incorrect — task detail belongs on a Level 2 or Level 3 map.",""],bookRef:"Book p. 102"},{id:"sv-2-617",phase:2,topic:"2.1.2",qtype:"best-action",difficulty:3,stem:'A quotation process has a step **"Review and re-approve the quotation"** because about one quote in four has pricing errors at the first approval. The manager wants to add a second reviewer to speed it up. What is the BEST response from the Black Belt?',options:["Treat the step as rework and look for the cause of the pricing errors upstream","Mark the step value-added, because it stops errors reaching customers","Move the step to the end of the process, after the quote is sent","Add the second reviewer, because faster reviews raise value-added time"],answer:0,hint:"'Re-' steps are very likely waste; fix why they happen.",steps:[{title:"Key idea",body:"'Review' and 're-approve' are classic NVA rework steps."},{title:"Apply to the stem",body:"Removing the cause of the pricing errors removes the need for the rework step."},{title:"Eliminate look-alikes",body:"Speeding up or relabelling the step keeps the waste."}],final:"Rework → fix the upstream cause → answer **A**",whyWrong:["","Incorrect — checking for errors does not change form, fit or function.","Incorrect — sending wrong quotes moves the problem to the customer.","Incorrect — a faster review is still a non-value-added repeat of work."],bookRef:"Book p. 117"},{id:"sv-2-618",phase:2,topic:"2.1.2",qtype:"output",difficulty:2,stem:`A team runs a symbol check on its draft service-fault map:

\`\`\`
Process Map — symbol check
Shape       Text                          Exits
Ellipse     Customer reports fault        1
Rectangle   Log ticket in ITSM tool       1
Diamond     Fault on customer side?       2 (Yes / No)
Rectangle   Dispatch field engineer       1
Diamond     Priority level?               3 (P1 / P2 / P3)
Ellipse     Ticket closed                 0
\`\`\`

Which element breaks the book's symbol rules?`,options:["The 'Log ticket in ITSM tool' rectangle","The 'Fault on customer side?' diamond","The 'Priority level?' diamond","The 'Ticket closed' ellipse"],answer:2,hint:"A decision may have only two paths.",steps:[{title:"Key idea",body:"Book rule: a diamond is a decision with only Yes and No paths."},{title:"Apply to the stem",body:"'Priority level?' has three exits, so it must be split into Yes/No decisions."}],final:"Three exits from a diamond → answer **C**",whyWrong:["Incorrect — it is an activity in a rectangle and starts with a verb.","Incorrect — it has exactly two exits, Yes and No, as required.","","Incorrect — an end ellipse has no exit after the process ends."],bookRef:"Book p. 101"},{id:"sv-2-619",phase:2,topic:"2.1.2",qtype:"output",difficulty:2,stem:`A swim lane map of an enterprise-order process gives this hand-off log:

\`\`\`
Swim Lane Map — hand-off log (median per order)
From lane          To lane            Wait (h)   Work at next step (min)
Sales              Credit Control        6            10
Credit Control     Provisioning         31            15
Provisioning       Field Engineering    52            90
Field Engineering  Billing               4             5
\`\`\`

Which conclusion is supported by the output?`,options:["Credit Control is the bottleneck because it has the most lanes","Billing is the bottleneck because its work time is the shortest","The longest wait is at the hand-off from Sales to Credit Control","The longest wait is at the hand-off from Provisioning to Field Engineering"],answer:3,hint:"Read the wait column; queues form at lane crossings.",steps:[{title:"Key idea",body:"Each lane crossing is a supplier–customer hand-off, where queues usually form."},{title:"Apply to the stem",body:"The largest printed wait is 52 h, from Provisioning to Field Engineering."}],final:"Largest wait: Provisioning → Field Engineering → answer **D**",whyWrong:["Incorrect — each step has one lane; lane count is not a measure here.","Incorrect — a short work time does not make a step a bottleneck.","Incorrect — 6 h is one of the shortest waits in the log.",""],bookRef:"Book p. 103"},{id:"sv-2-620",phase:2,topic:"2.1.2",qtype:"output",difficulty:3,stem:`A team classifies the steps of a new-line order process:

\`\`\`
Value-added check
Step                          Changes form/fit/function?  Customer pays?  Required by regulator?
Capture order                 No                          No              No
Verify ID document            No                          No              Yes
Configure SIM and number      Yes                         Yes             No
Re-enter order in billing     No                          No              No
\`\`\`

Which decision is supported by the table?`,options:["'Capture order' and 'Configure SIM and number' are both value-added","All four steps are value-added because each is needed to deliver the line","Only 'Configure SIM and number' is value-added; 'Verify ID document' is kept but minimised","'Verify ID document' is value-added because the regulator requires it"],answer:2,hint:"VA only if both answers are Yes; required NVA steps are kept small.",steps:[{title:"Key idea",body:"A step is VA when it changes form, fit or function and the customer would pay."},{title:"Apply to the stem",body:"Only 'Configure SIM and number' has Yes/Yes. 'Verify ID' is NVA but required by the regulator, so it is kept and minimised."}],final:"One VA step; required NVA kept small → answer **C**",whyWrong:["Incorrect — 'Capture order' fails both value-added questions in the table.","Incorrect — being needed is not the test; three steps fail both questions.","","Incorrect — a regulatory requirement keeps a step but does not make it value-added."],bookRef:"Book p. 117"},{id:"sv-2-621",phase:2,topic:"2.1.2",qtype:"output",difficulty:3,stem:`A value stream map summary for a device-repair process shows:

\`\`\`
Value Stream Map — yield summary
Step          First-pass yield
Receive          0.98
Diagnose         0.71
Repair           0.93
Test             0.96
Rolled throughput yield (RTY) = 0.62
\`\`\`

Which statement is supported by the output?`,options:["About 62% of the steps have no defects, and Receive is the quality bottleneck","The average yield of the steps is 0.62, and Test is the quality bottleneck","About 62% of devices pass all four steps first time, and Diagnose is the quality bottleneck","About 62% of devices fail at least one step, and Repair is the quality bottleneck"],answer:2,hint:"RTY = share of items passing every step first time.",steps:[{title:"Key idea",body:"RTY is the product of the step yields; it is the first-time pass rate for the whole process."},{title:"Apply to the stem",body:"Diagnose has the lowest printed yield (0.71), so it is the quality bottleneck."}],final:"62% pass first time; Diagnose lowest → answer **C**",whyWrong:["Incorrect — RTY is about items passing every step, not the share of steps.","Incorrect — RTY multiplies yields; it is not their average.","","Incorrect — 0.62 is the share that pass first time, not the share that fail."],bookRef:"Book p. 105"},{id:"sv-2-622",phase:2,topic:"2.1.2",qtype:"output",difficulty:3,stem:`A team exports its SIPOC worksheet for a SIM-replacement process:

\`\`\`
SIPOC — worksheet summary
Column        Entries
Suppliers     3
Inputs        7
Process       19 steps (incl. 6 Yes/No decisions)
Outputs       4
Customers     3
\`\`\`

What should the Black Belt change?`,options:["Reduce the process column to a high-level map of about 4–8 steps","Remove the customers column, because they are listed on the outputs","Add more suppliers so that there is one supplier per input","Add a decision diamond for every output"],answer:0,hint:"How much detail belongs in the 'P' of SIPOC?",steps:[{title:"Key idea",body:"The process column of a SIPOC is a high-level map of about 4–8 steps."},{title:"Apply to the stem",body:"19 steps with decisions is Level 2 detail; it should be rolled up."}],final:"P column → 4–8 steps → answer **A**",whyWrong:["","Incorrect — customers are a core column of a SIPOC.","Incorrect — several inputs can come from one supplier.","Incorrect — decisions belong on a detailed map, not a SIPOC."],bookRef:"Book p. 111"},{id:"sv-2-623",phase:2,topic:"2.1.2",qtype:"output",difficulty:2,stem:`A team compares three maps of a payroll process:

\`\`\`
Map   Steps shown   Decisions   Performance data
A          6           none        none
B         23           5           none
C         41           9           C/T, yield, DPU per task
\`\`\`

Which labelling of the maps is correct?`,options:["A = Level 1 macro, B = Level 2 worker, C = Level 3 micro","A = Level 2 worker, B = Level 1 macro, C = Level 3 micro","A = Level 1 macro, B = Level 3 micro, C = Level 2 worker","A = Level 3 micro, B = Level 2 worker, C = Level 1 macro"],answer:0,hint:"Detail and data grow from Level 1 to Level 3.",steps:[{title:"Key idea",body:"Level 1: few major steps; Level 2: worker steps with decisions; Level 3: adds performance data."},{title:"Apply to the stem",body:"A has 6 steps (macro), B adds decisions (worker), C adds C/T, yield and DPU (micro)."}],final:"A=L1, B=L2, C=L3 → answer **A**",whyWrong:["","Incorrect — six steps with no decisions is the macro view, Map A.","Incorrect — performance data marks Level 3, which is Map C.","Incorrect — this reverses the levels; Level 3 has the most detail."],bookRef:"Book pp. 102–103"},{id:"sv-2-624",phase:2,topic:"2.1.2",qtype:"true-false",difficulty:3,stem:"On a value stream map, the step with the largest number of items in its queue always has the most days of work waiting.",options:["True","False"],answer:1,hint:"Days in queue = queue × cycle time ÷ available time.",steps:[{title:"Key idea",body:"Days of work waiting combine the queue size, cycle time and available time."},{title:"Apply to the stem",body:"A smaller queue with a long cycle time can hold more days of work."}],final:"Not always → False → answer **B**",whyWrong:["Incorrect — days of work depend on the queue, the cycle time and the available time, not on the queue alone.",""],bookRef:"Book p. 105"},{id:"sv-2-625",phase:2,topic:"2.1.2",qtype:"true-false",difficulty:1,stem:"Rolled throughput yield along a value stream is found by multiplying the first-pass yields of all the steps.",options:["True","False"],answer:0,hint:"RTY combines the yields of every step.",steps:[{title:"Key idea",body:"RTY = yield₁ × yield₂ × … × yieldₙ."},{title:"Apply to the stem",body:"The statement describes this rule."}],final:"Multiply yields → True → answer **A**",whyWrong:["","Incorrect — RTY is the product of the step yields; averaging them is the common error."],bookRef:"Book p. 105"},{id:"sv-2-626",phase:2,topic:"2.1.2",qtype:"true-false",difficulty:1,stem:"A Level 1 map is the worker's view of the process.",options:["True","False"],answer:1,hint:"Management, worker, improvement — match to levels 1, 2, 3.",steps:[{title:"Key idea",body:"Level 1 = management view; Level 2 = worker view; Level 3 = improvement view."},{title:"Apply to the stem",body:"The statement gives Level 1 the Level 2 role."}],final:"Level 1 is management → False → answer **B**",whyWrong:["Incorrect — Level 1 is the macro, management view; the worker view is Level 2.",""],bookRef:"Book p. 102"},{id:"sv-2-627",phase:2,topic:"2.1.2",qtype:"true-false",difficulty:1,stem:"The book describes the process map as the most important and powerful tool for improving a process.",options:["True","False"],answer:0,hint:"How does the book introduce process mapping?",steps:[{title:"Key idea",body:"The book calls the process map the most important and powerful tool for improving a process."},{title:"Apply to the stem",body:"The statement matches the book."}],final:"True → answer **A**",whyWrong:["","Incorrect — the book does call the process map the most important and powerful improvement tool."],bookRef:"Book p. 99"},{id:"sv-2-628",phase:2,topic:"2.1.2",qtype:"sequence",difficulty:2,stem:`A team builds a SIPOC for a fibre-repair process. In the book's preferred order, in which sequence should these four elements be identified?

- **P** Customers
- **Q** Inputs
- **R** Outputs
- **S** Suppliers`,options:["R → Q → P → S","P → R → S → Q","S → Q → R → P","R → P → Q → S"],answer:3,hint:"Start from what the process delivers and to whom.",steps:[{title:"Key idea",body:"Preferred order: outputs → customers → (customer requirements) → inputs → suppliers."},{title:"Apply to the stem",body:"R (outputs), P (customers), Q (inputs), S (suppliers)."}],final:"R → P → Q → S → answer **D**",whyWrong:["Incorrect — inputs come only after the customers and their needs are known.","Incorrect — customers cannot be found before the outputs they receive.","Incorrect — this is the acronym order, not the preferred build order.",""],bookRef:"Book p. 111"},{id:"sv-2-629",phase:2,topic:"2.1.2",qtype:"sequence",difficulty:1,stem:`In which order does a project move through the three views of a process?

- **P** What the process should be
- **Q** What people think the process is
- **R** What the process actually is`,options:["R → Q → P","P → Q → R","Q → R → P","Q → P → R"],answer:2,hint:"Belief → reality → target.",steps:[{title:"Key idea",body:"People start with what they think; walking reveals what it actually is; the project delivers what it should be."},{title:"Apply to the stem",body:"Q → R → P."}],final:"Think → actually is → should be → answer **C**",whyWrong:["Incorrect — the belief exists before the team walks the process.","Incorrect — the target comes last, as the result of the project.","","Incorrect — the target cannot be set before the actual process is known."],bookRef:"Book p. 100"},{id:"sv-2-630",phase:2,topic:"2.1.2",qtype:"sequence",difficulty:1,stem:`A team drills down from the big picture to the detail. In which order are these maps produced?

- **P** Worker-view map with decisions
- **Q** Micro map with yields and cycle times
- **R** Macro map of 4–8 major steps`,options:["R → Q → P","P → R → Q","R → P → Q","Q → P → R"],answer:2,hint:"Level 1 → Level 2 → Level 3.",steps:[{title:"Key idea",body:"Macro (Level 1) → worker (Level 2) → micro (Level 3)."},{title:"Apply to the stem",body:"R → P → Q."}],final:"Macro → worker → micro → answer **C**",whyWrong:["Incorrect — performance data is added after the worker-level steps are known.","Incorrect — the macro map frames the worker map, so it comes first.","","Incorrect — this runs from detail up to the big picture."],bookRef:"Book pp. 102–103"},{id:"sv-2-631",phase:2,topic:"2.1.2",qtype:"sequence",difficulty:3,stem:`A team runs a value-added analysis on its customer-onboarding process. Put these activities in a logical order:

- **P** Mark each failing step with a red X or 'NVA'
- **Q** Walk the process to confirm the map shows what actually happens
- **R** Remove the unnecessary steps, and minimise those that must stay
- **S** Ask of each step: does it change form, fit or function, and would the customer pay?`,options:["S → Q → P → R","Q → S → P → R","Q → P → S → R","S → P → R → Q"],answer:1,hint:"Confirm the map → test → mark → act.",steps:[{title:"Key idea",body:"A VA analysis needs the actual process, then the two questions, then marking, then removal."},{title:"Apply to the stem",body:"Q → S → P → R."}],final:"Walk → test → mark → remove → answer **B**",whyWrong:["Incorrect — the steps tested must first be confirmed as real.","","Incorrect — steps cannot be marked before they are tested.","Incorrect — verification by walking comes before the analysis, not after removal."],bookRef:"Book pp. 107, 117"},{id:"sv-2-632",phase:2,topic:"2.1.2",qtype:"sequence",difficulty:3,stem:`From the data box of one value stream step, put these thinking steps in order to find how many days of work are waiting:

- **P** Multiply by the uptime to get the available time
- **Q** Divide the work waiting by the available time
- **R** Subtract the breaks from the shift time
- **S** Multiply the queue by the cycle time to get the work waiting`,options:["S → Q → R → P","R → P → S → Q","R → S → P → Q","P → R → S → Q"],answer:1,hint:"Available time = (shift − breaks) × uptime; days = work waiting ÷ available time.",steps:[{title:"Key idea",body:"First build the available time: shift minus breaks, then times uptime."},{title:"Apply to the stem",body:"Then the work waiting (queue × C/T) is divided by it: R → P → S → Q."}],final:"R → P → S → Q → answer **B**",whyWrong:["Incorrect — the division needs the available time, which is worked out from R and P first.","","Incorrect — the available time (R then P) is completed before the work waiting is compared.","Incorrect — uptime applies to the shift after breaks are removed."],bookRef:"Book p. 105"},{id:"sv-2-633",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"Where do the ratings in an X-Y matrix come from, according to the book?",options:["A designed experiment run on the process","Customer survey scores for each input","The team's collective opinions and process knowledge","Regression analysis of historical data"],answer:2,hint:"The book's warning: 'this is not real data'.",steps:[{title:"Key idea",body:"The X-Y matrix is based on the team's collective opinions ('tribal knowledge')."},{title:"Apply to the stem",body:"It is organised brainstorming, not measured data."}],final:"Team opinion → answer **C**",whyWrong:["Incorrect — experiments test X's later, in Improve; they do not fill the matrix.","Incorrect — customers help weight the Y's; they do not rate how each X affects them.","","Incorrect — regression is a data analysis in Analyze; the matrix comes before it."],bookRef:"Book p. 118"},{id:"sv-2-634",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"What can an X-Y matrix do that a fishbone diagram cannot?",options:["It is built by the team through brainstorming","It groups the causes into categories","It lists the possible causes of one effect","It rates each X against several weighted Y's at the same time"],answer:3,hint:"A fishbone has one effect at its head; how many Y's does the matrix handle?",steps:[{title:"Key idea",body:"The X-Y matrix assesses the relative impact of potential X's on multiple Y's, each Y weighted 1–10."},{title:"Eliminate look-alikes",body:"Listing, grouping and team brainstorming are shared with or belong to the fishbone."}],final:"Multiple weighted Y's at once → answer **D**",whyWrong:["Incorrect — both tools are team brainstorming tools.","Incorrect — grouping causes into categories is the fishbone's structure.","Incorrect — listing possible causes of one effect is what a fishbone does.",""],bookRef:"Book pp. 118–120"},{id:"sv-2-635",phase:2,topic:"2.1.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The book sums up the X-Y matrix as a team-based [?] tool for the potential X's.`,options:["Control","Measurement","Prioritisation","Verification"],answer:2,hint:"What does the matrix do to the long list of X's?",steps:[{title:"Key idea",body:"The X-Y matrix ranks the potential X's so the team studies the most likely ones first."},{title:"Eliminate look-alikes",body:"It does not control, measure or verify anything."}],final:"Prioritisation tool → answer **C**",whyWrong:["Incorrect — control tools such as SPC are used in the Control phase.","Incorrect — measurement systems are checked with MSA.","","Incorrect — verifying an X needs data and tests in Analyze."],bookRef:"Book p. 118"},{id:"sv-2-636",phase:2,topic:"2.1.3",qtype:"true-false",difficulty:3,stem:"When an input reaches the top of an X-Y matrix ranking, it has been shown to cause the change in the output.",options:["True","False"],answer:1,hint:"The book warns that the matrix is not real data.",steps:[{title:"Key idea",body:"The X-Y matrix prioritises X's for study; it does not prove causation."},{title:"Apply to the stem",body:"Top X's go forward to data collection and testing; some may turn out unimportant."}],final:"Not proven → False → answer **B**",whyWrong:["Incorrect — the ranking is team opinion; Analyze must test the top X's with data.",""],bookRef:"Book p. 118"},{id:"sv-2-637",phase:2,topic:"2.1.3",qtype:"statements",difficulty:2,stem:`Consider these statements about the X-Y matrix:

1. It assesses the relative impact of potential X's on multiple Y's.
2. It is completed once, at the end of Define, and then frozen.
3. It is filled in with measured data from designed experiments.
4. It should include all the customer-focused Y's.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Recall the book's four-point definition of the X-Y matrix.",steps:[{title:"Key idea",body:"Book: identify X's and their relative impact on multiple Y's (all customer-focused Y's); team opinion; every project; never completed."},{title:"Apply to the stem",body:"1 and 4 are true; 2 and 3 contradict the definition."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Statement 2 is false — the matrix is never completed and is updated when a parameter changes.","Statements 2 and 3 are false — it is a living document built from team opinion.","Statement 3 is false — the matrix is organised brainstorming, not measured data.",""],bookRef:"Book p. 118"},{id:"sv-2-638",phase:2,topic:"2.1.3",qtype:"not-except",difficulty:2,stem:"Each of the following is a step in filling in an X-Y matrix EXCEPT:",options:["Rate how often each X has failed in the past on a 1–10 occurrence scale","Score each X against each Y using 0, 1, 3 or 9","Weight each Y on a scale of 1 to 10","List the X's down the left side"],answer:0,hint:"Occurrence ratings belong to a different risk tool.",steps:[{title:"Key idea",body:"X-Y steps: list X's, list Y's, weight Y's 1–10, score X vs Y with 0/1/3/9, calculate and sort."},{title:"Apply to the stem",body:"Occurrence from failure history is an FMEA column."}],final:"Occurrence rating belongs to FMEA → answer **A**",whyWrong:["","Incorrect — scoring with 0/1/3/9 is a step.","Incorrect — weighting each Y from 1 to 10 is a step.","Incorrect — listing the inputs in rows is the first step."],bookRef:"Book pp. 120–121"},{id:"sv-2-639",phase:2,topic:"2.1.3",qtype:"best-action",difficulty:3,stem:`A team weighting the outputs of a billing X-Y matrix agrees that **billing accuracy** and **dispute resolution time** both deserve a weight of 10. The Black Belt insists that every Y must have a different weight and lowers one of them to 9 by coin toss.

Was this an appropriate action?`,options:["Yes, because each Y must have a unique weight for the ranking to work","Yes, because a coin toss removes bias from the weighting","No, because ties in the Y weights are acceptable in an X-Y matrix","No, because all Y's must be given the same weight of 10"],answer:2,hint:"What does the book say about equal weights?",steps:[{title:"Key idea",body:"Each Y is weighted 1–10 by importance, and the book notes that ties are fine."},{title:"Apply to the stem",body:"Forcing a difference by chance distorts the agreed importance of the outputs."}],final:"No — ties are fine → answer **C**",whyWrong:["Incorrect — the book says ties are fine when weighting the Y's.","Incorrect — a random change replaces the team's agreed judgement with chance.","","Incorrect — Y's are weighted 1–10 by importance, so weights can differ."],bookRef:"Book p. 120"},{id:"sv-2-640",phase:2,topic:"2.1.3",qtype:"output",difficulty:2,stem:`A team reviews part of its X-Y matrix before calculating the rankings:

\`\`\`
X-Y Matrix — scoring check (relationship scale 0/1/3/9)
Input (X)               FCR (w=10)   Handle time (w=7)   CSAT (w=8)
Knowledge-base search       9               3                 9
CRM screen speed            3               9                 1
Call-routing rule           1               5                 3
Headset model               0               1                 0
\`\`\`

Which entry does NOT follow the book's scoring scale?`,options:["Knowledge-base search against FCR","CRM screen speed against CSAT","Call-routing rule against Handle time","Headset model against FCR"],answer:2,hint:"Relationship scores use only 0, 1, 3 or 9.",steps:[{title:"Key idea",body:"Scores: 9 strong, 3 moderate, 1 weak, 0 none; weights on the Y's run 1–10."},{title:"Apply to the stem",body:"Call-routing rule vs Handle time shows 5, which is not on the 0/1/3/9 scale."}],final:"A score of 5 is invalid → answer **C**",whyWrong:["Incorrect — 9 (strong effect) is a valid score.","Incorrect — 1 (weak effect) is a valid score.","","Incorrect — 0 (no effect) is a valid score."],bookRef:"Book pp. 120–121"}];export{e as items};
